insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 17, 'E filho de Eliézer foi Reabias o primeiro. E Eliézer não teve outros filhos; mas os filhos de Reabias foram muitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 18, 'Filho de Izar foi Selomite o primeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 19, 'Os filhos de Hebrom: Jería o primeiro, Amarias o segundo, Jaaziel o terceiro, e Jecameão o quarto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 20, 'Os filhos de Uziel: Mica o primeiro, e Issias o segundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 21, 'Os filhos de Merari: Mali e Musi. Os filhos de Mali: Eleazar e Quis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 22, 'E morreu Eleazar sem filhos, mas teve filhas; e os filhos de Quis, seus irmãos, as tomaram por mulheres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 23, 'Os filhos de Musi: Mali, Éder e Jeremote, eles três.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 24, 'Estes são os filhos de Levi nas famílias de seus pais, cabeceiras de famílias em suas linhagens, contados por seus nomes, por suas cabeças, os quais faziam obra no ministério da casa do SENHOR, de vinte anos acima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 25, 'Porque Davi disse: o SENHOR Deus de Israel há dado repouso a seu povo Israel, e o habitar em Jerusalém para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 26, 'E também os levitas não levarão mais o tabernáculo, e todos seus vasos para seu ministério.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 27, 'Assim que, conforme as últimas palavras de Davi, foi a contagem dos filhos de Levi de vinte anos acima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 28, 'E estavam sob a mão dos filhos de Arão, para ministrar na casa do SENHOR, nos átrios e nas câmaras, e na purificação de toda coisa santificada, e na demais obra do ministério da casa de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 29, 'Assim para os pães da proposição, e para a flor da farinha para o sacrifício, e para os pães sem levedura, e para as coisas postas em panelas, e para o tostado, e para toda medida e conta;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 30, 'E para que assistissem cada manhã todos os dias a confessar e louvar a o SENHOR, e assim à tarde;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 31, 'E para oferecer todos os holocaustos a o SENHOR os sábados, novas luas, e solenidades, por a conta e forma que tinham, continuamente diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 23, 32, 'E para que tivessem a guarda do tabernáculo do testemunho, e a guarda do santuário, e as ordens dos filhos de Arão seus irmãos, no ministério da casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 1, 'Também os filhos de Arão tiveram suas repartições. Os filhos de Arão: Nadabe, Abiú, Eleazar e Itamar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 2, 'Mas Nadabe, e Abiú morreram antes que seu pai, e não tiveram filhos: Eleazar e Itamar tiveram o sacerdócio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 3, 'E Davi os repartiu, sendo Zadoque dos filhos de Eleazar, e Aimeleque dos filhos de Itamar, por seus turnos em seu ministério.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 4, 'E os filhos de Eleazar foram achados, quanto a seus principais varões, muitos mais que os filhos de Itamar; e repartiram-nos assim: Dos filhos de Eleazar havia dezesseis cabeças de famílias paternas; e dos filhos de Itamar pelas famílias de seus pais, oito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 5, 'Repartiram-nos, pois, por sorte os uns com os outros: porque dos filhos de Eleazar e dos filhos de Itamar havia príncipes do santuário, e príncipes da casa de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 6, 'E Semaías escriba, filho de Natanael, dos levitas, escreveu-os diante do rei e dos príncipes, e diante de Zadoque o sacerdote, e de Aimeleque filho de Abiatar, e dos príncipes das famílias dos sacerdotes e levitas; e inscreviam uma família a Eleazar, e a Itamar outra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 7, 'E a primeira sorte saiu por Jeoiaribe, a segunda por Jedaías;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 8, 'A terceira por Harim, a quarta por Seorim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 9, 'A quinta por Malquias, a sexta por Miamim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 10, 'A sétiam por Coz, a oitava por Abias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 11, 'A nona por Jesua, a décima por Secanias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 12, 'A décima primeira por Eliasibe, a décima segunda por Jaquim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 13, 'A décima terceira por Hupá, a décima quarta por Jesebeabe;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 14, 'A décima quinta por Bilga, a décima sexta por Imer;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 15, 'A décima sétima por Hezir, a décima outiva por Hapises;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 16, 'A décima nona por Petaías, a vigésima por Jeezquel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 17, 'A vigésima primeira por Jaquim, a vigésima segunda por Gamul;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 18, 'A vigésima terceira por Delaías, a vigésima quarta por Maazias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 19, 'Estes foram contados em seu ministério, para que entrassem na casa do SENHOR, conforme a sua ordenança, sob o mando de Arão seu pai, da maneira que lhe havia mandado o SENHOR o Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 20, 'E dos filhos de Levi que restaram: Subael, dos filhos de Anrão; e dos filhos de Subael, Jedias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 21, 'E dos filhos de Reabias, Issias o principal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 22, 'Dos izaritas, Selomote; e filho de Selomote, Jaate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 23, 'E dos filhos de Hebrom; Jerias o primeiro, o segundo Amarias, o terceiro Jaaziel, o quarto Jecameão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 24, 'Filho de Uziel, Mica; e filho de Mica, Samir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 25, 'Irmão de Mica, Issias; e filho de Issias, Zacarias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 26, 'Os filhos de Merari: Mali e Musi; filho de Jaazias, Beno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 27, 'Os filhos de Merari por Jaazias: Beno, e Soão, Zacur e Ibri.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 28, 'E de Mali, Eleazar, o qual não teve filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 29, 'Filho de Quis, Jerameel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 30, 'Os filhos de Musi: Mali, Éder e Jeremote. Estes foram os filhos dos levitas conforme às casas de suas famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 24, 31, 'Estes também lançaram sortes, como seus irmãos os filhos de Arão, diante do rei Davi, e de Zadoque e de Aimeleque, e dos príncipes das famílias dos sacerdotes e levitas: o principal dos pais igualmente que o menor de seus irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 1, 'Assim Davi e os príncipes do exército apartaram para o ministério a os filhos de Asafe, e de Hemã, e de Jedutum, os quais profetizassem com harpas, saltérios, e címbalos: e o número deles foi, de homens idôneos para a obra de seu ministério'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 2, 'Dos filhos de Asafe: Zacur, José, Netanias, e Asarela, filhos de Asafe, sob a direção de Asafe, o qual profetizava à ordem do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 3, 'De Jedutum: os filhos de Jedutum, Gedalias, Zeri, Jesaías, Hasabias, e Matitias, e Simei: seis, sob a mão de seu pai Jedutum, o qual profetizava com harpa, para celebrar e louvar a o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 4, 'De Hemã: os filhos de Hemã, Buquias, Matanias, Uziel, Sebuel, Jeremote, Hananias, Hanani, Eliata, Gidalti, Romanti-Ezer, Josbecasa, Maloti, Hotir, e Maaziote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 5, 'Todos estes foram filhos de Hemã, vidente do rei em palavras de Deus, para exaltar o poder seu: e deu Deus a Hemã catorze filhos e três filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 6, 'E todos estes estavam sob a direção de seu pai na música, na casa do SENHOR, com címbalos, saltérios e harpas, para o ministério do templo de Deus, por disposição do rei acerca de Asafe, de Jedutum, e de Hemã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 7, 'E o número deles com seus irmãos instruídos em música do SENHOR, todos os aptos, foi duzentos oitenta e oito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 8, 'E lançaram sortes para os turnos do serviço, entrando o pequeno com o grande, o mesmo o mestre que o discípulo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 9, 'E a primeira sorte saiu por Asafe, a José: a segunda a Gedalias, quem com seus irmãos e filhos foram doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 10, 'A terceira a Zacur, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 11, 'A quarta a Izri, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 12, 'A quinta a Netanias, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 13, 'A sexta a Buquias, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 14, 'A sétima a Jesarela, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 15, 'A oitava a Jesaías, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 16, 'A nona a Matanias, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 17, 'A décima a Simei, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 18, 'A décima primeira a Azareel, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 19, 'A décima segunda a Hasabias, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 20, 'A décima terceira a Subael, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 21, 'A décima quarta a Matitias, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 22, 'A décima quinta a Jeremote, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 23, 'A décima sexta a Hananias, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 24, 'A décima sétima a Josbecasa, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 25, 'A décima oitava a Hanani, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 26, 'A décima nona a Maloti, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 27, 'A vigésima a Eliata, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 28, 'A vigésima primeira a Hotir, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 29, 'A vigésima segunda a Gidalti, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 30, 'A vigésima terceira a Maaziote, com seus filhos e seus irmãos, doze;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 25, 31, 'A vigésima quarta a Romanti-Ezer, com seus filhos e seus irmãos, doze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 1, 'Quanto às repartições dos porteiros: Dos coraítas: Meselemias filho de Coré, dos filhos de Asafe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 2, 'Os filhos de Meselemias: Zacarias o primogênito, Jediael o segundo, Zebadias o terceiro, Jatniel o quarto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 3, 'Elão o quinto, Joanã o sexto, Elioenai o sétimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 4, 'Os filhos de Obede-Edom: Semaías o primogênito, Jozabade o segundo, Joabe o terceiro, o quarto Sacar, o quinto Natanael;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 5, 'O sexto Amiel, o sétimo Issacar, o oitavo Peuletai: porque Deus havia abençoado a Obede-Edom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 6, 'Também de Semaías seu filho nasceram filhos que foram senhores sobre a casa de seus pais; porque eram varões muito valentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 7, 'Os filhos de Semaías: Otni, Rafael, Obede, Elzabade, e seus irmãos, homens esforçados; assim Eliú, e Semaquias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 8, 'Todos estes dos filhos de Obede-Edom: eles com seus filhos e seus irmãos, homens robustos e fortes para o ministério; sessenta e dois, de Obede-Edom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 9, 'E os filhos de Meselemias e seus irmãos, dezoito homens valentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 10, 'De Hosa, dos filhos de Merari: Sinri o principal, (ainda que não fosse o primogênito, mas seu pai o pôs para que fosse cabeça);'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 11, 'O segundo Hilquias, o terceiro Tebalias, o quarto Zacarias: todos os filhos de Hosa e seus irmãos foram treze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 12, 'Entre estes se fez a distribuição dos porteiros, alternando os principais dos varões na guarda com seus irmãos, para servir na casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 13, 'E lançaram sortes, o pequeno com o grande, pelas casas de seus pais, para cada porta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 14, 'E caiu a sorte ao oriente a Selemias. E a Zacarias seu filho, conselheiro entendido, lançaram as sortes, e sua sorte foi para o norte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 15, 'E por Obede-Edom, ao sul; e por seus filhos, a casa dos depósitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 16, 'Por Supim e Hosa ao ocidente, com a porta de Salequete ao caminho da subida, guarda contra guarda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 17, 'Ao oriente seis levitas, ao norte quatro de dia; ao sul quatro de dia; e à casa dos depósitos, de dois em dois.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 18, 'Em a câmara dos vasos ao ocidente, quatro ao caminho, e dois na câmara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 19, 'Estes são as repartições dos porteiros, filhos dos coraítas, e dos filhos de Merari.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 20, 'E dos levitas, Aías tinha cargo dos tesouros da casa de Deus, e dos tesouros das coisas santificadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 21, 'Quanto a os filhos de Ladã, filhos de Gérson: de Ladã, os príncipes das famílias de Ladã foram Gérson, e Jeieli.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 22, 'Os filhos de Jeieli, Zetã e Joel seu irmão, tiveram cargo dos tesouros da casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 23, 'Acerca dos anramitas, dos izaritas, dos hebronitas, e dos uzielitas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 24, 'Sebuel filho de Gérson, filho de Moisés, era principal sobre os tesouros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 25, 'Em ordem a seu irmão Eliézer, filho deste era Reabias, filho deste Jesaías, filho deste Jorão, filho deste Zicri, do que foi filho Selomote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 26, 'Este Selomote e seus irmãos tinham cargo de todos os tesouros de todas as coisas santificadas, que havia consagrado o rei Davi, e os príncipes das famílias, e os capitães de milhares e de centenas, e os chefes do exército;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 27, 'De o que haviam consagrado das guerras e dos despojos, para reparar a casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 28, 'Assim todas as coisas que havia consagrado Samuel vidente, e Saul filho de Quis, e Abner filho de Ner, e Joabe filho de Zeruia: e todo o que qualquer um consagrava, estava sob a mão de Selomote e de seus irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 29, 'Dos izaritas, Quenanias e seus filhos eram governadores e juízes sobre Israel nas obras de fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 30, 'Dos hebronitas, Hasabias e seus irmãos, homens de vigor, mil e setecentos, governavam a Israel da outra parte do Jordão, ao ocidente, em toda a obra do SENHOR, e no serviço do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 31, 'Dos hebronitas, Jerias era o principal entre os hebronitas repartidos em suas linhagens por suas famílias. No ano quarenta do reinado de Davi se registraram, e acharam-se entre eles fortes e vigorosos em Jazer de Gileade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 26, 32, 'E seus irmãos, homens valentes, eram dois mil e setecentos, cabeças de famílias, os quais o rei Davi constituiu sobre os rubenitas, gaditas, e sobre a meia tribo de Manassés, para todas as coisas de Deus, e os negócios do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 1, 'E os filhos de Israel segundo seu número, a saber, príncipes de famílias, comandantes, centuriões e oficiais dos que serviam ao rei em todos os negócios das divisões que entravam e saíam cada mês em todos os meses do ano, eram em cada divisão vinte e quatro mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 2, 'Sobre a primeira divisão do primeiro mês estava Jasobeão filho de Zabdiel; e havia em sua divisão vinte e quatro mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 3, 'Dos filhos de Perez foi ele chefe de todos os capitães das companhias do primeiro mês.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 4, 'Sobre a divisão do segundo mês estava Dodai aoíta: e Miclote era maior general em sua divisão, na que também havia vinte e quatro mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 5, 'O chefe da terceira divisão para o terceiro mês era Benaia, filho de Joiada sumo sacerdote; e em sua divisão havia vinte e quatro mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 6, 'Este Benaia era valente entre os trinta e sobre os trinta; e em sua divisão estava Amizabade seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 7, 'O quarto chefe para o quarto mês era Asael irmão de Joabe, e depois dele Zebadias seu filho; e em sua divisão havia vinte e quatro mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 8, 'O quinto chefe para o quinto mês era Samute izraíta: e em sua divisão havia vinte e quatro mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 9, 'O sexto para o sexto mês era Ira filho de Iques, de Tecoa; e em sua divisão vinte e quatro mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 10, 'O sétimo para o sétimo mês era Helez pelonita, dos filhos de Efraim; e em sua divisão vinte e quatro mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 11, 'O oitavo para o oitavo mês era Sibecai husatita, de Zerá; e em sua divisão vinte e quatro mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 12, 'O nono para o nono mês era Abiezer anatotita, dos benjamitas; e em sua divisão vinte e quatro mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 13, 'O décimo para o décimo mês era Maarai netofatita, de Zerá; e em sua divisão vinte e quatro mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 14, 'O décimo primeiro para o décimo primeiro mês era Benaia piratonita, dos filhos de Efraim; e em sua divisão vinte e quatro mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 15, 'O décimo segundo para o décimo segundo mês era Heldai netofatita, de Otniel; e em sua divisão vinte e quatro mil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 16, 'Assim sobre as tribos de Israel: o chefe dos rubenitas era Eliézer filho de Zicri; dos simeonitas, Sefatias, filho de Maaca:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 17, 'Dos levitas, Hasabias filho de Quemuel; dos aronitas, Zadoque;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 18, 'De Judá, Eliú, um dos irmãos de Davi; dos de Issacar, Onri filho de Micael.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 19, 'Dos de Zebulom, Ismaías filho de Obadias; dos de Naftali, Jeremote filho de Azriel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 20, 'Dos filhos de Efraim, Oseias filho de Azazias; da meia tribo de Manassés, Joel filho de Pedaías;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 21, 'De a outra meia tribo de Manassés em Gileade, Ido filho de Zacarias; dos de Benjamim, Jaasiel filho de Abner;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 22, 'E de Dã, Azarel filho de Jeroão. Estes foram os chefes das tribos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 23, 'E não tomou Davi o número dos que eram de vinte anos abaixo, porquanto o SENHOR havia dito que ele havia de multiplicar a Israel como as estrelas do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 24, 'Joabe filho de Zeruia havia começado a contar, mas não acabou, pois por isto veio a ira sobre Israel: e assim o número não foi posto no registro das crônicas do rei Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 25, 'E Azmavete filho de Adiel tinha cargo dos tesouros do rei; e dos tesouros dos campos, e das cidades, e das aldeias e castelos, Jônatas filho de Uzia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 26, 'E dos que trabalhavam na lavoura das terras, Ezri filho de Quelube;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 27, 'E das vinhas Simei ramatita; e do fruto das vinhas para as adegas, Zabdias sifmita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 28, 'E dos olivais e figueirais que havia nas campinas, Baal-Hanã gederita; e dos armazéns do azeite, Joás;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 29, 'Das vacas que pastavam em Sarom, Sitrai saronita; e das vacas que estavam nos vales, Safate filho de Adlai;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 30, 'E dos camelos, Obil ismaelita; e das asnas, Jedias meronotita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 31, 'E das ovelhas, Jaziz hagareno. Todos estes eram superintendentes da riqueza do rei Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 32, 'E Jônatas, tio de Davi, era conselheiro, homem prudente e escriba; e Jeiel filho de Hacmoni estava com os filhos do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 33, 'E também Aitofel era conselheiro do rei; e Husai arquita amigo do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 27, 34, 'Depois de Aitofel era Joiada filho de Benaia, e Abiatar. E Joabe era o general do exército do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 1, 'E juntou Davi em Jerusalém a todos os principais de Israel, os príncipes das tribos, e os chefes das divisões que serviam ao rei, os comandantes e centuriões, com os superintendentes de toda a riqueza e possessão do rei, e seus filhos, com os eunucos, os poderosos, e todos os seus homens valentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 2, 'E levantando-se o rei Davi, posto em pé disse: Ouvi-me, irmãos meus, e povo meu. Eu tinha em propósito edificar uma casa, para que nela repousasse a arca do pacto do SENHOR, e para o estrado dos pés de nosso Deus; e havia já aprontei tudo para edificar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 3, 'Mas Deus me disse: Tu não edificarás casa a meu nome: porque és homem de guerra, e derramaste muito sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 4, 'Porém o SENHOR o Deus de Israel me elegeu de toda a casa de meu pai, para que perpetuamente fosse rei sobre Israel: porque a Judá escolheu por chefe, e da casa de Judá a família de meu pai; e de entre os filhos de meu pai agradou-se de mim para me constituir rei sobre todo Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 5, 'E de todos meus filhos (porque o SENHOR me deu muitos filhos,) elegeu a meu filho Salomão para que se sente no trono do reino do SENHOR sobre Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 6, 'E me disse: Salomão teu filho, ele edificará minha casa e meus átrios: porque a este me escolhi por filho, e eu lhe serei a ele por pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 7, 'Assim eu confirmarei seu reino para sempre, se ele se esforçar a executar meus mandamentos e meus juízos, como este dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 8, 'Agora, pois, diante dos olhos de todo Israel, congregação do SENHOR, e em ouvidos de nosso Deus, guardai e inquiri todos os preceitos do SENHOR vosso Deus, para que possuais a boa terra, e a deixeis por herdade a vossos filhos depois de vós perpetuamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 9, 'E tu, Salomão, meu filho, conhece o Deus de teu pai, e serve-o com coração completo e ânimo voluntário; porque o SENHOR examina os corações de todos, e entende todas as intenções dos pensamentos. Se tu o buscares, o acharás; mas se o deixares, ele te rejeitará para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 10, 'Olha, pois, agora que o SENHOR te escolheu para que edifiques casa para santuário: esforça-te, e faze-a.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 11, 'E Davi deu a Salomão seu filho a planta do pórtico, e de suas casas, e de suas oficinas, e de suas salas, e de suas recâmaras, e da casa do propiciatório.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 12, 'Assim a planta de todas as coisas que tinha em sua vontade, para os átrios da casa do SENHOR, e para todas as câmaras em derredor, para os tesouros da casa de Deus, e para os tesouros das coisas santificadas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 13, 'Também para as ordens dos sacerdotes e dos levitas, e para toda a obra do ministério da casa do SENHOR, e para todos os vasos do ministério da casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 14, 'E deu ouro por peso para o de ouro, para todos os vasos de cada serviço: e prata por peso para todos os vasos, para todos os vasos de cada serviço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 15, 'Ouro por peso para os candelabros de ouro, e para suas lâmpadas; por peso o ouro para cada candelabro e suas lâmpadas: e para os candelabros de prata, prata por peso para o candelabro e suas lâmpadas, conforme ao serviço de cada candelabro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 16, 'Assim deu ouro por peso para as mesas da proposição, para cada mesa: do mesmo modo prata para as mesas de prata:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 17, 'Também ouro puro para os garfos e para as bacias, e para os incensários, e para as taças de ouro, para cada taça por peso; e para as taças de prata, por peso para cada taça:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 18, 'Ademais, ouro puro por peso para o altar do incenso, e para ele a maneira de carro dos querubins de ouro, que com as asas estendidas cobriam a arca do pacto do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 19, 'Todas estas coisas, disse Davi, se me representaram pela mão do SENHOR que me fez entender todas as obras do desenho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 20, 'Disse mais Davi a Salomão seu filho: Anima-te e esforça-te, e efetua-o; não temas, nem desmaies, porque o Deus o SENHOR, meu Deus, será contigo: ele não te deixará, nem te desamparará, até que acabes toda a obra para o serviço da casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 28, 21, 'Eis aqui as ordens dos sacerdotes e dos levitas, para todo o ministério da casa de Deus, serão contigo em toda a obra: assim todos os voluntários e inteligentes para qualquer espécie de artifício; e os príncipes, e todo o povo para executar todas as tuas ordens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 1, 'Depois disse o rei Davi a toda a assembleia: A só Salomão meu filho elegeu Deus; ele é jovem e tenro, e a obra grande; porque a casa não é para homem, mas sim para o SENHOR Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 2, 'Eu, porém, com todas as minhas forças preparei, para a casa de meu Deus, ouro para as coisas de ouro, e prata para as coisas de prata, e bronze para as de bronze, e ferro para as de ferro, e madeira para as de madeira, e pedras de ônix, e pedras decorativas, e pedras negras, e pedras de diversas cores, e toda sorte de pedras preciosas, e pedras de mármore em abundância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 3, 'A mais disto, porquanto tenho meu gosto na casa de meu Deus, eu guardo em meu tesouro particular ouro e prata que, ademais de todas as coisas que aprontei para a casa do santuário, ei dado para a casa de meu Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 4, 'A saber, três mil talentos de ouro, de ouro de Ofir, e sete mil talentos de prata refinada para cobrir as paredes das casas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 5, 'Ouro, pois, para as coisas de ouro, e prata para as coisas de prata, e para toda a obra de mãos dos oficiais. E quem quer fazer hoje oferta a o SENHOR?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 6, 'Então os príncipes das famílias, e os príncipes das tribos de Israel, comandantes e centuriões, com os superintendentes da riqueza do rei, ofereceram de sua vontade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 7, 'E deram para o serviço da casa de Deus cinco mil talentos de ouro e dez mil moedas, e dez mil talentos de prata, e dezoito mil talentos de bronze, e cinco mil talentos de ferro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 8, 'E todo o que se achou com pedras preciosas, deu-as para o tesouro da casa do SENHOR, em mão de Jeiel gersonita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 9, 'E folgou-se o povo de haver contribuído de sua vontade; porque com inteiro coração ofereceram a o SENHOR voluntariamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 10, 'Assim folgou-se muito o rei Davi, e abençoou a o SENHOR diante de toda a congregação; e disse Davi: Bendito sejas tu, ó o SENHOR, Deus de Israel nosso pai, de um século a outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 11, 'Tua é, ó o SENHOR, a magnificência, e o poder, e a glória, a vitória, e a honra; porque todas as coisas que estão nos céus e na terra são tuas. Teu, ó o SENHOR, é o reino, e a altura sobre todos os que estão por cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 12, 'As riquezas e a glória estão diante de ti, e tu senhoreias a todos: e em tua mão está a potência e a fortaleza, e em tua mão a grandeza e força de todas as coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 13, 'Agora, pois, Deus nosso, nós te confessamos, e louvamos teu glorioso nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 14, 'Porque quem sou eu, e quem é meu povo, para que pudéssemos oferecer de nossa vontade coisas semelhantes? Porque tudo é teu, e o que recebemos de tua mão te damos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 15, 'Porque nós, estrangeiros e peregrinos somos diante de ti, como todos nossos pais; e nossos dias qual sombra sobre a terra, e não dão espera.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 16, 'Ó SENHOR Deus nosso, toda esta abundância que preparamos para edificar casa a teu santo nome, de tua mão é, e tudo é teu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 17, 'Eu sei, Deus meu, que tu esquadrinhas os corações, e que a retidão te agrada: por isso eu com retidão de meu coração voluntariamente te ei oferecido tudo isto, e agora vi com alegria que teu povo, que aqui se achou agora, deu para ti espontaneamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 18, 'SENHOR, Deus de Abraão, de Isaque, e de Israel, nossos pais, conserva perpetuamente esta vontade do coração de teu povo, e encaminha seu coração a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 19, 'E ao meu filho Salomão dá um coração íntegro, para que guarde os teus mandamentos, os teus testemunhos e os teus estatutos, e para que faça todas as coisas, e te edifique a casa para a qual eu preparei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 20, 'Depois disse Davi a toda à congregação: Bendizei agora ao SENHOR vosso Deus. Então toda a congregação bendisse ao SENHOR Deus de seus pais, e inclinando-se, adoraram diante do SENHOR, e do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 21, 'E sacrificaram animais ao SENHOR, e ofereceram ao SENHOR holocaustos no dia seguinte, mil bezerros, mil carneiros, mil cordeiros com as suas libações, e muitos sacrifícios por todo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 22, 'E comeram e beberam diante do SENHOR aquele dia com grande alegria; e deram a segunda vez a investidura do reino a Salomão filho de Davi, e ungiram-no ao SENHOR por príncipe, e a Zadoque por sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 23, 'E sentou-se Salomão por rei no trono do SENHOR em lugar de Davi seu pai, e foi próspero; e obedeceu-lhe todo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 24, 'E todos os príncipes e poderosos, e todos os filhos do rei Davi, prestaram homenagem ao rei Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 25, 'E o SENHOR engrandeceu em extremo a Salomão a os olhos de todo Israel, e deu-lhe glória do reino, qual nenhum rei a teve antes dele em Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 26, 'Assim reinou Davi filho de Jessé sobre todo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 27, 'E o tempo que reinou sobre Israel foi quarenta anos. Sete anos reinou em Hebrom, e trinta e três reinou em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 28, 'E morreu em boa velhice, cheio de dias, de riquezas, e de glória: e reinou em seu lugar Salomão seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 29, 'E os feitos do rei Davi, primeiros e últimos, estão escritos no livro das crônicas de Samuel vidente, e nas crônicas do profeta Natã, e nas crônicas de Gade vidente,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 13, '1 Crônicas', '1Cr', 29, 30, 'Com todo o relato de seu reinado, e seu poder, e os tempos que passaram sobre ele, e sobre Israel, e sobre todos os reinos daquelas aquelas terras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 1, 1, 'E Salomão filho de Davi foi estabelecido em seu reino; e o SENHOR seu Deus foi com ele, e lhe engrandeceu muito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 1, 2, 'E chamou Salomão a todo Israel, comandantes, líderes de centenas, e juízes, e a todos os príncipes de todo Israel, cabeças de famílias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 1, 3, 'E foi Salomão, e com ele toda esta congregação, ao alto que havia em Gibeão; porque ali estava o tabernáculo do testemunho de Deus, que Moisés servo do SENHOR havia feito no deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 1, 4, 'Mas Davi havia trazido a arca de Deus de Quriate-Jearim ao lugar que ele lhe havia preparado; porque ele lhe havia estendido uma tenda em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 1, 5, 'Assim o altar de bronze que havia feito Bezalel filho de Uri filho de Hur, estava ali diante do tabernáculo do SENHOR, ao qual Salomão foi a consultar com aquela congregação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 1, 6, 'Subiu, pois, Salomão ali diante do SENHOR, ao altar de bronze que estava no tabernáculo do testemunho, e ofereceu sobre ele mil holocaustos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 1, 7, 'E aquela noite apareceu Deus a Salomão, e disse-lhe: Pede o que queres que eu te dê.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 1, 8, 'E Salomão disse a Deus: Tu fizeste com Davi meu pai grande misericórdia, e a mim me puseste por rei em seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 1, 9, 'Confirme-se, pois, agora, ó SENHOR Deus, tua palavra dada a Davi meu pai; porque tu me puseste por rei sobre um povo em multidão como o pó da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 1, 10, 'Dá-me agora sabedoria e conhecimento, para sair e entrar diante deste povo: porque quem poderá julgar este teu povo tão grande?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 1, 11, 'E disse Deus a Salomão: Porquanto isto foi em teu coração, que não pediste riquezas, riqueza, ou glória, nem a alma dos que te querem mal, nem pediste muitos dias, mas sim que pediste para ti sabedoria e conhecimento para julgar meu povo, sobre o qual te constituí por rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 1, 12, 'Sabedoria e conhecimento te são dados; e também te darei riquezas, bens, e glória, que nunca houve nos reis que foram antes de ti, nem depois de ti haverá tais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 1, 13, 'E voltou Salomão a Jerusalém do alto que estava em Gibeão, de ante o tabernáculo do testemunho; e reinou sobre Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 1, 14, 'E juntou Salomão carros e cavaleiros; e teve mil e quatrocentos carros, e doze mil cavaleiros, os quais pôs nas cidades dos carros, e com o rei em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 1, 15, 'E pôs o rei prata e ouro em Jerusalém como pedras, e cedro como sicômoros que nascem nos campos em abundância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 1, 16, 'E traziam cavalos do Egito e de Coa para Salomão; pois os mercadores do rei [os] compravam de Coa por [um certo] preço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 1, 17, 'E subiam, e tiravam do Egito, um carro por seiscentas peças de prata, e um cavalo por cento e cinquenta: e assim se tiravam por meio deles para todos os reis dos Heteus, e para os reis da Síria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 2, 1, 'Determinou, pois, Salomão edificar casa ao nome do SENHOR, e outra casa para seu reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 2, 2, 'E contou Salomão setenta mil homens que levassem cargas, e oitenta mil homens que cortassem no monte, e três mil e seiscentos que os governassem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 2, 3, 'E enviou a dizer Salomão a Hirão rei de Tiro: Faze comigo como fizeste com Davi meu pai, enviando-lhe cedros para que edificasse para si casa em que morasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 2, 4, 'Eis aqui eu tenho que edificar casa ao nome do SENHOR meu Deus, para consagrá-la, para queimar perfumes aromáticos diante dele, e para a colocação contínua dos pães da proposição, e para holocaustos a manhã e tarde, e os sábados, e luas novas, e festividades do SENHOR nosso Deus; o qual será perpétuo em Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 2, 5, 'E a casa que tenho que edificar, há de ser grande: porque o Deus nosso é grande sobre todos os deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 2, 6, 'Mas quem será tão poderoso que lhe edifique casa? Os céus e os céus dos céus não lhe podem compreender; quem, pois, sou eu, que lhe edifique casa, a não ser para queimar perfumes diante dele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 2, 7, 'Envia-me, pois, agora um homem hábil, que saiba trabalhar em ouro, e em prata, e em bronze, e em ferro, em púrpura, e em carmesim, e em azul, e que saiba esculpir com os mestres que estão comigo em Judá e em Jerusalém, os quais preparou meu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 2, 8, 'Envia-me também madeira de cedro, de faia, de pinho, do Líbano: porque eu sei que teus servos entendem de cortar madeira no Líbano; e eis que meus servos irão com os teus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 2, 9, 'Para que me preparem muita madeira, porque a casa que tenho de edificar há de ser grande e imponente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 2, 10, 'E eis que para os operários teus servos, cortadores da madeira, ei dado vinte mil coros de trigo em grão, e vinte mil coros de cevada, e vinte mil batos de vinho, e vinte mil batos de azeite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 2, 11, 'Então Hirão rei de Tiro respondeu por carta, a qual enviou a Salomão: Porque o SENHOR amou a seu povo, te pôs por rei sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 2, 12, 'E ademais dizia Hirão: Bendito seja o SENHOR o Deus de Israel, que fez os céus e a terra, e que deu ao rei Davi filho sábio, entendido, de bom senso e prudente, que edifique casa ao SENHOR, e casa para seu reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 2, 13, 'Eu, pois, te enviei um homem hábil e entendido, que foi de Hirão meu pai,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 2, 14, 'Filho de uma mulher das filhas de Dã, mas seu pai foi de Tiro; o qual sabe trabalhar em ouro, e prata, e bronze, e ferro, em pedra e em madeira, em púrpura, e em azul, em linho e em carmesim; assim para esculpir todas as figuras, e tirar toda sorte de desenho que lhe for proposto, e [estar] com teus homens peritos, e com os do meu senhor Davi, teu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 2, 15, 'Agora, pois, enviará meu senhor a seus servos o trigo e cevada, e azeite e vinho, que disse;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 2, 16, 'E nós cortaremos no Líbano a madeira que houveres necessidade, e te a traremos em balsas pelo mar até Jope, e tu a farás levar até Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 2, 17, 'E contou Salomão todos os homens estrangeiros que estavam na terra de Israel, depois de havê-los já contado Davi seu pai, e foram achados cento cinquenta e três mil seiscentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 2, 18, 'E assinalou deles setenta mil para levar cargas, e oitenta mil que cortassem no monte, e três mil e seiscentos por capatazes para fazer trabalhar ao povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 3, 1, 'E começou Salomão a edificar a casa em Jerusalém, no monte Moriá que havia sido mostrado a Davi seu pai, no lugar que Davi havia preparado na eira de Ornã jebuseu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 3, 2, 'E começou a edificar no mês segundo, a dois do mês, no quarto ano de seu reinado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 3, 3, 'Estas são as medidas de que Salomão fundou o edifício da casa de Deus. A primeira medida foi do comprimento de sessenta côvados; e a largura de vinte côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 3, 4, 'O pórtico que estava na dianteira do comprimento, era de vinte côvados à frente da largura da casa, e sua altura de cento e vinte: e cobriu-o por dentro de ouro puro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 3, 5, 'E forrou a casa maior com madeira de faia, a qual cobriu de bom ouro, e fez ressaltar sobre ela palmas e correntes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 3, 6, 'Cobriu também a casa de pedras preciosas por excelência: e o ouro era ouro de Parvaim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 3, 7, 'Assim cobriu a casa, suas vigas, seus umbrais, suas paredes, e suas portas, com ouro; e esculpiu querubins pelas paredes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 3, 8, 'Fez assim a casa do lugar santíssimo, cujo comprimento era de vinte côvados segundo a largura da frente da casa, e sua largura de vinte côvados: e cobriu-a de bom ouro que pesava seiscentos talentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 3, 9, 'E o peso dos pregos teve cinquenta siclos de ouro. Cobriu também de ouro as salas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 3, 10, 'E dentro do lugar santíssimo fez dois querubins esculpidos, os quais cobriram de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 3, 11, 'O comprimento das asas dos querubins era de vinte côvados: porque a uma asa era de cinco côvados: a qual chegava até a parede da casa; e a outra asa de cinco côvados, a qual chegava à asa do outro querubim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 3, 12, 'Da mesma maneira a uma asa do outro querubim era de cinco côvados: a qual chegava até a parede da casa; e a outra asa era de cinco côvados, que tocava a asa do outro querubim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 3, 13, 'Assim as asas destes querubins estavam estendidas por vinte côvados: e eles estavam em pé com os rostos até a casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 3, 14, 'Fez também o véu de azul, púrpura, carmesim e linho, e fez ressaltar em ele querubins.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 3, 15, 'Diante da casa fez duas colunas de trinta e cinco côvados de comprimento, com seus capitéis encima, de cinco côvados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 3, 16, 'Fez também correntes, [como no] compartimento interno, e as pôs sobre os capitéis das colunas: e fez cem romãs, as quais pôs nas correntes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 3, 17, 'E assentou as colunas diante do templo, a uma à mão direita, e a outra à esquerda; e à da mão direita chamou Jaquim, e à da esquerda, Boaz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 1, 'Fez ademais um altar de bronze de vinte côvados de comprimento, e vinte côvados de largura, e dez côvados de altura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 2, 'Também fez um mar de fundição, o qual tinha dez côvados do uma borda à outra, inteiramente redondo: sua altura era de cinco côvados, e uma linha de trinta côvados o contornava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 3, 'E debaixo dele havia figuras de bois que o circundavam, dez em cada côvado todo ao redor: eram duas ordens de bois fundidos juntamente com o mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 4, 'E estava assentado sobre doze bois, três dos quais estavam voltados ao norte, e três ao ocidente, e três ao sul, e três ao oriente: e o mar assentava sobre eles, e todas suas traseiras estavam à parte de dentro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 5, 'E tinha de espessura um palmo, e a borda era da feitura da borda de um cálice, ou flor de lírio. E fazia três mil batos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 6, 'Fez também dez fontes, e pôs cinco à direita e cinco à esquerda, para lavar e limpar nelas a obra do holocausto; mas o mar era para os sacerdotes se lavarem nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 7, 'Fez também dez candelabros de ouro segundo sua forma, os quais pôs no templo, cinco à direita, e cinco à esquerda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 8, 'Também fez dez mesas e as pôs no templo, cinco à direita, e cinco à esquerda: igualmente fez cem bacias de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 9, 'A mais disto fez o átrio dos sacerdotes, e o grande átrio, e as entradas do átrio, e cobriu as portas de elas de bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 10, 'E assentou o mar ao lado direito até o oriente, em frente do sul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 11, 'Fez também Hirão caldeiras, e pás, e bacias; e acabou Hirão a obra que fazia ao rei Salomão para a casa de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 12, 'Duas colunas, e os globos, os capitéis sobre as cabeças das duas colunas, e duas redes para cobrir as duas bolas dos capitéis que estavam encima das colunas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 13, 'Quatrocentas romãs nas duas redes, duas ordens de romãs em cada rede, para que cobrissem as duas bolas dos capitéis que estavam encima das colunas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 14, 'Fez também as bases, sobre as quais assentou as pias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 15, 'O mar, e doze bois debaixo dele;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 16, 'E caldeiras, e pás, e garfos; e todos seus utensílios fez Hirão seu pai ao rei Salomão para a casa do SENHOR, de bronze puríssimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 17, 'E fundiu-os o rei nas planícies do Jordão, em terra argilosa, entre Sucote e Zeredá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 18, 'E Salomão fez todos estes vasos em grande abundância, porque não pode ser achado o peso do bronze.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 19, 'Assim fez Salomão todos os vasos para a casa de Deus, e o altar de ouro, e as mesas sobre as quais se punham os pães da proposição;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 20, 'Assim os candelabros e suas lâmpadas, de ouro puro, para que as acendessem diante do compartimento interno conforme à costume.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 21, 'E as flores, e as lâmpadas, e as tenazes se fizeram completamente de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 4, 22, 'Também os apagadores, e as bacias, e as colheres, e os incensários, de ouro puro. Quanto à entrada da casa, suas portas interiores para o lugar santíssimo, e as portas da casa do templo, de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 5, 1, 'E acabada que foi toda a obra que fez Salomão para a casa do SENHOR, meteu Salomão nela as coisas que Davi seu pai havia dedicado; e pôs a prata, e o ouro, e todos os vasos, nos tesouros da casa de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 5, 2, 'Então Salomão juntou em Jerusalém os anciãos de Israel, e todos os príncipes das tribos, os cabeças das famílias dos filhos de Israel, para que trouxessem a arca do pacto do SENHOR da cidade de Davi, que é Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 5, 3, 'E juntaram-se ao rei todos os varões de Israel, à solenidade do mês sétimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 5, 4, 'E vieram todos os anciãos de Israel, e tomaram os levitas a arca:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 5, 5, 'E levaram a arca, e o tabernáculo do testemunho, e todos os vasos do santuário que estavam no tabernáculo: os sacerdotes e os levitas os levaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 5, 6, 'E o rei Salomão, e toda a congregação de Israel que se havia a ele reunido diante da arca, sacrificaram ovelhas e bois, que pela abundância não se puderam contar nem numerar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 5, 7, 'E os sacerdotes meteram a arca do pacto do SENHOR em seu lugar, no compartimento interno da casa, no lugar santíssimo, sob as asas dos querubins:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 5, 8, 'Pois os querubins estendiam as asas sobre o assento da arca, e cobriam os querubins por encima assim a arca como suas barras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 5, 9, 'E fizeram sair fora as barras, de modo que se vissem as cabeças das barras da arca diante do compartimento interno , mas não se viam desde fora: e ali estiveram até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 5, 10, 'No arca nada havia, a não serem as duas tábuas que Moisés havia posto em Horebe, com as quais o SENHOR havia feito aliança com os filhos de Israel, depois que saíram do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 5, 11, 'E quando os sacerdotes saíram do santuário, (porque todos os sacerdotes que se acharam haviam sido santificados, e não guardavam suas vezes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 5, 12, 'E os levitas cantores, todos os de Asafe, os de Hemã, e os de Jedutum, juntamente com seus filhos e seus irmãos, vestidos de linho fino, estavam com címbalos e saltérios e harpas ao oriente do altar; e com eles cento vinte sacerdotes que tocavam trombetas);'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 5, 13, 'Soavam, pois, as trombetas, e cantavam com a voz todos a uma, para louvar e confessar ao SENHOR: e quando levantavam a voz com trombetas e címbalos e instrumentos de música, quando louvavam ao SENHOR, dizendo: Porque é bom, porque sua misericórdia é para sempre; então a casa, [isto é] ,a casa do SENHOR, se encheu de uma nuvem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 5, 14, 'E os sacerdotes não podiam ficar em pé para ministrar, por causa da nuvem; porque a glória do SENHOR havia enchido a casa de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 1, 'Então disse Salomão: o SENHOR disse que ele habitaria na escuridão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 2, 'Eu, pois, edifiquei uma casa de morada para ti, e uma habitação em que mores para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 3, 'E voltando o rei seu rosto, abençoou a toda a congregação de Israel: e toda a congregação de Israel estava em pé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 4, 'E ele disse: Bendito seja o SENHOR Deus de Israel, o qual com sua mão cumpriu o que falou por sua boca a Davi meu pai, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 5, 'Desde o dia que tirei meu povo da terra do Egito, nenhuma cidade escolhi de todas as tribos de Israel para edificar casa de onde estivesse meu nome, nem escolhi homem que fosse príncipe sobre meu povo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 6, 'Mas a Jerusalém escolhi para que nela esteja meu nome, e a Davi escolhi para que fosse sobre meu povo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 7, 'E Davi meu pai teve no coração edificar casa ao nome do SENHOR Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 8, 'Mas o SENHOR disse a Davi meu pai: Com respeito a haver tido em teu coração edificar casa a meu nome, bem fizeste em haver tido isto em teu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 9, 'Porém tu não edificarás a casa, mas sim teu filho que sairá de teus lombos, ele edificará casa a meu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 10, 'E o SENHOR cumpriu sua palavra que havia dito, pois eu me levantei em lugar de Davi meu pai, e sentei-me no trono de Israel, como o SENHOR havia dito, e edifiquei casa ao nome do SENHOR Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 11, 'E nela pus a arca, na qual está o pacto do SENHOR que estabeleceu com os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 12, 'Pôs-se logo Salomão diante do altar do SENHOR, em presença de toda a congregação de Israel, e estendeu suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 13, 'Porque Salomão havia feito uma plataforma de bronze, de cinco côvados de comprimento, e de cinco côvados de largura, e de altura de três côvados, e o havia posto em meio do átrio: e pôs-se sobre ela, e ficou de joelhos diante de toda a congregação de Israel, e estendendo suas mãos ao céu, disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 14, 'Ó SENHOR Deus de Israel, não há Deus semelhante a ti no céu nem na terra, que guardas o pacto e a misericórdia a teus servos que caminham diante de ti de todo seu coração;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 15, 'Que guardaste a teu servo Davi meu pai o que lhe disseste: tu o disseste de tua boca, mas com tua mão o cumpriste, como parece este dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 16, 'Agora, pois, SENHOR Deus de Israel, guarda a teu servo Davi meu pai o que lhe prometeste, dizendo: Não faltará de ti homem diante de mim, que se sente no trono de Israel, a condição que teus filhos guardem seu caminho, andando em minha lei, como tu diante de mim andaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 17, 'Agora, pois, ó SENHOR Deus de Israel, verifique-se tua palavra que disseste a teu servo Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 18, 'Mas é verdade que Deus habitará com o homem na terra? Eis aqui, os céus e os céus dos céus não podem conter-te: quanto menos esta casa que edifiquei?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 19, 'Mas tu olharás à oração de teu servo, e a seu rogo, ó SENHOR Deus meu, para ouvir o clamor e a oração com que teu servo ora diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 20, 'Que teus olhos estejam abertos sobre esta casa de dia e de noite, sobre o lugar do qual disseste, Meu nome estará ali; que oigas a oração com que teu servo ora em este lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 21, 'Assim que ouças o rogo de teu servo, e de teu povo Israel, quando em este lugar fizerem oração, que tu ouvirás desde os céus, desde o lugar de tua morada: que ouças e perdoes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 22, 'Se alguém pecar contra seu próximo, e ele lhe pedir juramento fazendo-lhe jurar, e o juramento vier diante de teu altar nesta casa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 23, 'Tu ouvirás desde os céus, e operarás, e julgarás a teus servos, dando a paga ao ímpio, voltando-lhe seu proceder sobre sua cabeça, e justificando ao justo em dar-lhe conforme a sua justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 24, 'Se o teu povo Israel cair diante dos inimigos, por haver pecado contra ti, e se converterem, e confessarem teu nome, e rogarem diante de ti nesta casa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 25, 'Tu ouvirás desde os céus, e perdoarás o pecado de teu povo Israel, e os voltarás à terra que deste a eles e a seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 26, 'Se os céus se fecharem, que não haja chuvas por haver pecado contra ti, se orarem a ti em este lugar, e confessarem teu nome, e se converterem de seus pecados, quando os afligires,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 27, 'Tu os ouvirás nos céus, e perdoarás o pecado de teus servos e de teu povo Israel, e lhes ensinarás o bom caminho para que andem nele, e darás chuva sobre tua terra, a qual deste por herdade a teu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 28, 'E se houver fome na terra, ou se houver pestilência, se houver ferrugem ou mofo, locusta ou pulgão; ou se os cercarem seus inimigos na terra de seu domicílio; qualquer praga ou enfermidade que seja;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 29, 'Toda oração e todo rogo que fizer qualquer homem, ou todo teu povo Israel, qualquer um que conhecer sua chaga e sua dor em seu coração, se estender suas mãos a esta casa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 30, 'Tu ouvirás desde os céus, desde o lugar de tua habitação, e perdoarás, e darás a cada um conforme a seus caminhos, havendo conhecido seu coração; (porque só tu conheces o coração dos filhos dos homens);'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 31, 'Para que te temam e andem em teus caminhos, todos os dias que viverem sobre a face da terra que tu deste aos nossos pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 32, 'E também ao estrangeiro que não for de teu povo Israel, que houver vindo de distantes terras a causa de teu grande nome, e de tua mão forte, e de teu braço estendido, se vierem, e orarem em esta casa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 33, 'Tu ouvirás desde os céus, desde o lugar de tua morada, e farás conforme a todas as coisas pelas quais houver clamado a ti o estrangeiro; para que todos os povos da terra conheçam teu nome, e te temam como teu povo Israel, e saibam que teu nome é invocado sobre esta casa que eu edifiquei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 34, 'Se teu povo sair à guerra contra seus inimigos pelo caminho que tu os enviares, e orarem a ti até esta cidade que tu escolheste, até a casa que edifiquei a teu nome,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 35, 'Tu ouvirás desde os céus sua oração e seu rogo, e ampararás seu direito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 36, 'Se pecarem contra ti, (pois não há ser humano que não peque), e te irares contra eles, e os entregares diante de seus inimigos, para que os que os tomarem os levem cativos à terra de inimigos, distante ou próxima,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 37, 'e eles se conscientizarem na terra de onde forem levados cativos; se se converterem, e orarem a ti na terra de seu cativeiro, e disserem: Pecamos, fizemos perversidade, agimos com maldade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 38, 'se se converterem a ti de todo o seu coração e de toda a sua alma na terra de seu cativeiro, aonde forem levados cativos, e orarem até sua terra que tu deste a seus pais, até a cidade que tu escolheste, e até a casa que edifiquei a teu nome;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 39, 'Tu ouvirás desde os céus, desde o lugar de tua morada, sua oração e seu rogo, e ampararás sua causa, e perdoarás a teu povo que pecou contra ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 40, 'Agora, pois, ó Deus meu, rogo-te estejam abertos teus olhos, e atentos teus ouvidos à oração em este lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 41, 'Ó SENHOR Deus, levanta-te agora para habitar em teu repouso, tu e a arca de tua fortaleza; sejam, ó SENHOR Deus, vestidos de saúde teus sacerdotes, e regozijem de bem teus santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 6, 42, 'SENHOR Deus, não faças virar o rosto de teu ungido: lembra-te das misericórdias de Davi teu servo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 1, 'E quando Salomão acabou de orar, o fogo desceu dos céus, e consumiu o holocausto e as vítimas; e a glória do SENHOR encheu a casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 2, 'E não podiam entrar os sacerdotes na casa do SENHOR, porque a glória do SENHOR havia enchido a casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 3, 'E quando viram todos os filhos de Israel descer o fogo e a glória do SENHOR sobre a casa, caíram em terra sobre seus rostos no pavimento, e adoraram, confessando ao SENHOR e dizendo: Que é bom, que sua misericórdia é para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 4, 'Então o rei e todo o povo sacrificaram vítimas diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 5, 'E ofereceu o rei Salomão em sacrifício vinte e dois mil bois, e cento e vinte mil ovelhas; e assim dedicaram a casa de Deus o rei e todo o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 6, 'E os sacerdotes assistiam em seu ministério; e os levitas com os instrumentos de música do SENHOR, os quais havia feito o rei Davi para confessar ao SENHOR, que sua misericórdia é para sempre; quando Davi louvava por mão deles. Assim os sacerdotes tinham trombetas diante deles, e todo Israel estava em pé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 7, 'Salomão também santificou o meio do átrio que estava diante da casa do SENHOR, porquanto havia oferecido ali os holocaustos, e a gordura dos sacrifícios pacíficos; porque no altar de bronze que Salomão havia feito, não podiam caber os holocaustos, e a oferta de alimentos, e as gorduras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 8, 'Então fez Salomão festa durante sete dias, e com ele todo Israel, uma grande congregação, desde a entrada de Hamate até o ribeiro do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 9, 'Ao oitavo dia fizeram convocação, porque haviam feito a dedicação do altar em sete dias, e haviam celebrado a solenidade por sete dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 10, 'E aos vinte e três do mês sétimo enviou ao povo a suas moradas, alegres e jubilosos de coração pelos benefícios que o SENHOR havia feito a Davi, e a Salomão, e a seu povo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 11, 'Acabou pois Salomão a casa do SENHOR, e a casa do rei: e todo o que Salomão teve em vontade de fazer na casa do SENHOR e em sua casa, foi próspero.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 12, 'E apareceu o SENHOR a Salomão de noite, e disse-lhe: Eu ei ouvido tua oração, e escolhi para mim este lugar por casa de sacrifício.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 13, 'Se eu fechar os céus, que não haja chuva, e se mandar à locusta que consuma a terra, ou se enviar pestilência a meu povo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 14, 'Se se humilhar meu povo, sobre os quais nem nome é invocado, e orarem, e buscarem meu rosto, e se converterem de seus maus caminhos; então eu ouvirei desde os céus, e perdoarei seus pecados, e sararei sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 15, 'Agora estarão abertos meus olhos, e atentos meus ouvidos, à oração em este lugar:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 16, 'Pois que agora escolhi e santifiquei esta casa, para que esteja nela meu nome para sempre; e meus olhos e meu coração estarão aí para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 17, 'E tu, se andares diante de mim, como andou Davi teu pai, e fizeres todas as coisas que eu te ei mandado, e guardares meus estatutos e meus direitos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 18, 'Eu confirmarei o trono de teu reino, como estabeleci com Davi teu pai, dizendo: Não faltará homem de ti que domine em Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 19, 'Mas se vós vos desviardes, e deixardes meus estatutos e meus preceitos que vos propus, e fordes e servirdes a deuses alheios, e os adorardes,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 20, 'Eu os arrancarei de minha terra que lhes dei; e esta casa que ei santifiquei a meu nome, eu a lançarei de diante de mim, e a porei por provérbio e fábula em todos os povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 21, 'E esta casa que haverá sido ilustre, será espanto a todo o que passar, e dirá: Por que há feito assim o SENHOR a esta terra e a esta casa?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 7, 22, 'E se responderá: Por quanto deixaram ao SENHOR Deus de seus pais, o qual os tirou da terra do Egito, e abraçaram deuses alheios, e os adoraram e serviram: por isso ele trouxe todo este mal sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 8, 1, 'E aconteceu que ao fim de vinte anos que Salomão havia edificado a casa do SENHOR e sua casa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 8, 2, 'Reedificou Salomão as cidades que Hirão lhe havia dado, e estabeleceu nelas aos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 8, 3, 'Depois veio Salomão a Hamate de Zobá, e a tomou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 8, 4, 'E edificou a Tadmor no deserto, e todas as cidades de armazéns que edificou em Hamate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 8, 5, 'Assim reedificou a Bete-Horom a de acima, e a Bete-Horom a de abaixo, cidades fortificadas, de muros, portas, e barras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 8, 6, 'E a Baalate, e a todas as vilas de armazéns que Salomão tinha; também todas as cidades dos carros e as de cavaleiros; e tudo o que Salomão quis edificar em Jerusalém, e no Líbano, e em toda a terra de seu senhorio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 8, 7, 'E a todo o povo que havia restado dos heteus, amorreus, perizeus, heveus, e Jebuseos, que não eram de Israel,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 8, 8, 'Os filhos dos que haviam restado na terra depois deles, aos quais os filhos de Israel não destruíram do todo, fez Salomão tributários até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 8, 9, 'E dos filhos de Israel não pôs Salomão servos em sua obra; porque eram homens de guerra, e seus príncipes e seus capitães, e comandantes de seus carros, e seus cavaleiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 8, 10, 'E tinha Salomão duzentos e cinquenta principais dos governadores, os quais mandavam naquela gente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 8, 11, 'E passou Salomão à filha de Faraó, da cidade de Davi à casa que ele lhe havia edificado; porque disse: Minha mulher não morará na casa de Davi rei de Israel, porque aquelas habitações de onde entrou a arca do SENHOR, são sagradas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 8, 12, 'Então ofereceu Salomão holocaustos ao SENHOR sobre o altar do SENHOR, que havia ele edificado diante do pórtico,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 8, 13, 'Para que oferecessem cada coisa em seu dia, conforme ao mandamento de Moisés, nos sábados, nas novas luas, e nas solenidades, três vezes no ano, a saber, na festa dos pães ázimos, na festa das semanas, e na festa das cabanas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 8, 14, 'E constituiu as repartições dos sacerdotes em seus ofícios, conforme à ordenação de Davi seu pai; e os levitas por suas ordens, para que louvassem e ministrassem diante dos sacerdotes, casa coisa em seu dia; assim os porteiros por sua ordem'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 8, 15, 'E não saíram do mandamento do rei, quanto aos sacerdotes e levitas, e os tesouros, e todo negócio:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 8, 16, 'Porque toda a obra de Salomão estava preparada desde o dia em que a casa do SENHOR foi fundada até que se acabou, até que a casa do SENHOR foi acabada do tudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 8, 17, 'Então Salomão foi a Eziom-Geber, e a Elote, à costa do mar na terra de Edom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 8, 18, 'Porque Hirão lhe havia enviado navios por mão de seus servos, e marinheiros destros no mar, os quais foram com os servos de Salomão a Ofir, e tomaram de ali quatrocentos e cinquenta talentos de ouro, e os trouxeram ao rei Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 1, 'E ouvindo a rainha de Sabá a fama de Salomão, veio a Jerusalém com uma comitiva muito grande, com camelos carregados de aroma, e ouro em abundância, e pedras preciosas, para tentar a Salomão com perguntas difíceis. E logo que veio a Salomão, falou com ele tudo o que havia em seu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 2, 'Porém Salomão lhe declarou todas suas palavras: nenhuma coisa restou que Salomão não lhe declarasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 3, 'E vendo a rainha de Sabá a sabedoria de Salomão, e a casa que havia edificado,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 4, 'E as iguarias de sua mesa, e o assento de seus servos, e o estado de seus criados, e os vestidos deles, seus mestres-salas e seus vestidos, e sua subida por de onde subia à casa do SENHOR, não restou mais espírito nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 5, 'E disse ao rei: Verdade é o que havia ouvido em minha terra de tuas coisas e de tua sabedoria;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 6, 'Mas eu não cria as palavras deles, até que ei vindo, e meus olhos viram: e eis que que nem ainda a metade da grandeza de tua sabedoria me havia sido dita; porque tu excedes a fama que eu havia ouvido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 7, 'Bem-aventurados teus homens, e ditosos estes teus servos, que estão sempre diante de ti, e ouvem tua sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 8, 'o SENHOR teu Deus seja bendito, o qual se agradou em ti para te pôr sobre seu trono por rei do SENHOR teu Deus: porquanto teu Deus amou a Israel para firmá-lo perpetuamente, por isso te pôs por rei sobre eles, para que faças juízo e justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 9, 'E deu ao rei cento e vinte talentos de ouro, e grande quantidade de aromas, e pedras preciosas: nunca havia tais aromas como os que deu a rainha de Sabá ao rei Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 10, 'Também os servos de Hirão e os servos de Salomão, que haviam trazido o ouro de Ofir, trouxeram madeira de cipreste, e pedras preciosas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 11, 'E fez o rei da madeira de cipreste degraus na casa do SENHOR, e nas casas reais, e harpas e saltérios para os cantores: nunca em terra de Judá se havia visto madeira semelhante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 12, 'E o rei Salomão deu à rainha de Sabá tudo o que ela quis e lhe pediu, mais de o que havia trazido ao rei. Depois se voltou e foi-se a sua terra com seus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 13, 'E o peso de ouro que vinha a Salomão cada um ano, era seiscentos sessenta e seis talentos de ouro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 14, 'Sem o que traziam os mercadores e negociantes; e também todos os reis da Arábia e os príncipes da terra traziam ouro e prata a Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 15, 'Fez também o rei Salomão duzentos paveses de ouro de martelo, cada um dos quais tinha seiscentos siclos de ouro lavrado:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 16, 'Assim trezentos escudos de ouro batido, tendo cada escudo trezentos siclos de ouro: e os pôs o rei na casa do bosque do Líbano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 17, 'Fez ademais o rei um grande trono de marfim, e cobriu-o de ouro puro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 18, 'E havia seis degraus ao trono, com um estrado de ouro ao mesmo, e braços da uma parte e da outra ao lugar do assento, e dois leões que estavam junto aos braços.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 19, 'Havia também ali doze leões sobre os seis degraus da uma parte e da outra. Jamais foi feito outro semelhante em reino algum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 20, 'Todos os utensílios do rei Salomão eram de ouro, e todos os utensílios da casa do bosque do Líbano, de ouro puro. Nos dias de Salomão a prata não era de valiosa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 21, 'Porque a frota do rei ia a Társis com os servos de Hirão, e cada três anos faziam vir os navios de Társis, e traziam ouro, prata, marfim, macacos, e pavões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 22, 'E excedeu o rei Salomão a todos os reis da terra em riqueza e em sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 23, 'E todos os reis da terra procuravam ver o rosto de Salomão, por ouvir sua sabedoria, que Deus havia posto em seu coração:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 24, 'E destes, cada um trazia o seu presente, vasos de prata, vasos de ouro, vestidos, armas, aromas, cavalos e mulas, todos os anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 25, 'Teve também Salomão quatro mil estábulos para os cavalos e carros, e doze mil cavaleiros, os quais pôs nas cidades dos carros, e com o rei em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 26, 'E teve senhorio sobre todos os reis desde o rio até a terra dos filisteus, e até o termo do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 27, 'E pôs o rei prata em Jerusalém como pedras, e cedros como os sicômoros que nascem pelas campinas em abundância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 28, 'Traziam também cavalos para Salomão, do Egito e de todas as províncias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 29, 'Os demais feitos de Salomão, primeiros e últimos, não está tudo escrito nos livros de Natã profeta, e na profecia de Aías silonita, e nas profecias do vidente Ido contra Jeroboão filho de Nebate?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 30, 'E reinou Salomão em Jerusalém sobre todo Israel quarenta anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 9, 31, 'E descansou Salomão com seus pais, e sepultaram-no na cidade de Davi seu pai: e reinou em seu lugar Roboão seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 1, 'E Roboão foi a Siquém porque em Siquém se havia juntado todo Israel para fazê-lo rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 2, 'E quando o ouviu Jeroboão filho de Nebate, o qual estava em Egito, de onde havia fugido por causa do rei Salomão, voltou do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 3, 'E enviaram e chamaram-lhe. Veio, pois, Jeroboão, e todo Israel, e falaram a Roboão, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 4, 'Teu pai agravou nosso jugo: alivia tu, pois, agora algo da dura servidão, e do grave jugo com que teu pai nos pressionou, e te serviremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 5, 'E ele lhes disse: Voltai a mim daqui a três dias. E o povo se foi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 6, 'Então o rei Roboão tomou conselho com os anciãos, que haviam estado diante de Salomão seu pai quando vivia, e disse-lhes: Como aconselhais vós que responda a este povo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 7, 'E eles lhe falaram, dizendo: Se te conduzires humanamente com este povo, e os agradares, e lhes falares boas palavras, eles te servirão perpetuamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 8, 'Mas ele, deixando o conselho que lhe deram os anciãos, tomou conselho com os rapazes que se haviam criado com ele, e que diante dele assistiam;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 9, 'E disse-lhes: Que aconselhais vós que respondamos a este povo, que me falou, dizendo: Alivia algo do jugo que teu pai pôs sobre nós?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 10, 'Então os rapazes que se haviam criado com ele, lhe falaram, dizendo: Assim dirás ao povo que te falou dizendo, Teu pai agravou nosso jugo, mas tu livra-nos da carga: assim lhes dirás: O meu dedo mínimo é mais espesso que os lombos de meu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 11, 'Assim que, meu pai vos impôs carga de grave jugo, e eu acrescentarei a vosso jugo: meu pai vos castigou com açoites, e eu com escorpiões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 12, 'Veio, pois, Jeroboão com todo o povo a Roboão ao terceiro dia: segundo o rei lhes havia mandado dizendo: Voltai a mim daqui a três dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 13, 'E respondeu-lhes o rei asperamente; pois deixou o rei Roboão o conselho dos anciãos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 14, 'E falou-lhes conforme ao conselho dos rapazes, dizendo: Meu pai agravou vosso jugo, e eu acrescentarei a vosso jugo: meu pai vos castigou com açoites, e eu com escorpiões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 15, 'E não escutou o rei ao povo; porque a causa era de Deus, para cumprir o SENHOR sua palavra que havia falado, por Aías silonita, a Jeroboão filho de Nebate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 16, 'E vendo todo Israel que o rei não lhes havia ouvido, respondeu o povo ao rei, dizendo: Que parte temos nós com Davi, nem herança no filho de Jessé? Israel, cada um a suas moradas! Davi, olha agora por tua casa! Assim se foi todo Israel a suas casas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 17, 'Mas reinou Roboão sobre os filhos de Israel que habitavam nas cidades de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 18, 'Enviou logo o rei Roboão a Adorão, que tinha cargo dos tributos; mas lhe apedrejaram os filhos de Israel, e morreu. Então se esforçou o rei Roboão, e subindo em um carro fugiu a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 10, 19, 'Assim se separou Israel da casa de Davi até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 1, 'E quando veio Roboão a Jerusalém, juntou da casa de Judá e de Benjamim cento e oitenta mil homens escolhidos de guerra, para lutar contra Israel e voltar o reino a Roboão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 2, 'Mas foi palavra do SENHOR a Semaías homem de Deus, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 3, 'Fala a Roboão filho de Salomão, rei de Judá, e a todos os israelitas em Judá e Benjamim, dizendo-lhes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 4, 'Assim disse o SENHOR: Não subais nem luteis contra vossos irmãos; volte-se casa um a sua casa, porque eu fiz este negócio. E eles ouviram a palavra do SENHOR, e voltaram-se, e não foram contra Jeroboão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 5, 'E habitou Roboão em Jerusalém, e edificou cidades para fortificar a Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 6, 'E edificou a Belém, e a Etã, e a Tecoa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 7, 'E a Bete-Zur, e a Socó, e a Adulão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 8, 'E a Gate, e a Maressa, e a Zife,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 9, 'E a Adoraim, e a Laquis, e a Azeca,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 10, 'E a Zorá, e a Aijalom, e a Hebrom, que eram em Judá e em Benjamim, cidades fortes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 11, 'Fortificou também as fortalezas, e pôs nelas capitães, e alimentos, e vinho, e azeite;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 12, 'E em todas as cidades, escudos e lanças. Fortificou-as pois em grande maneira, e Judá e Benjamim lhe estavam sujeitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 13, 'E os sacerdotes e levitas que estavam em todo Israel, se juntaram a ele de todos seus termos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 14, 'Porque os levitas deixavam seus campos e suas possessões, e se vinham a Judá e a Jerusalém: pois Jeroboão e seus filhos os lançavam do ministério do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 15, 'E ele se fez sacerdotes para os altos, e para os demônios, e para os bezerros que ele havia feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 16, 'Além daqueles acudiram também de todas as tribos de Israel os que haviam posto seu coração em buscar ao SENHOR Deus de Israel; e vieram-se a Jerusalém para sacrificar ao SENHOR, o Deus de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 17, 'Assim fortificaram o reino de Judá, e confirmaram a Roboão filho de Salomão, por três anos; porque três anos andaram no caminho de Davi e de Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 18, 'E tomou-se Roboão por mulher a Maalate, filha de Jeremote filho de Davi, e a Abiail, filha de Eliabe filho de Jessé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 19, 'A qual lhe gerou filhos: a Jeus, e a Samaria, e a Zaaão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 20, 'Depois dela tomou a Maaca filha de Absalão, a qual lhe pariu a Abias, a Atai, Ziza, e Selomite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 21, 'Mas Roboão amou a Maaca filha de Absalão sobre todas suas mulheres e concubinas; porque tomou dezoito mulheres e sessenta concubinas, e gerou vinte e oito filhos e sessenta filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 22, 'E pôs Roboão a Abias filho de Maaca por cabeça e príncipe de seus irmãos, porque queria fazer-lhe rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 11, 23, 'E fez-lhe instruir, e dispersou todos os seus filhos por todas as terras de Judá e de Benjamim, e por todas as cidades fortes, e deu-lhes alimentos em abundância, e buscou para eles muitas mulheres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 12, 1, 'E quando Roboão havia confirmado o reino, deixou a lei do SENHOR, e com ele todo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 12, 2, 'E no quinto ano do rei Roboão subiu Sisaque rei do Egito contra Jerusalém, (porquanto se haviam rebelado contra o SENHOR,)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 12, 3, 'Com mil e duzentos carros, e com sessenta mil cavaleiros: mas o povo que vinha com ele do Egito, não tinha número; a saber, de líbios, suquitas, e etíopes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 12, 4, 'E tomou as cidades fortes de Judá, e chegou até Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 12, 5, 'Então veio Semaías profeta a Roboão e aos príncipes de Judá, que estavam reunidos em Jerusalém por causa de Sisaque, e disse-lhes: Assim disse o SENHOR: Vós me deixastes, e eu também vos deixei em mãos de Sisaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 12, 6, 'E os príncipes de Israel e o rei se humilharam, e disseram: Justo é o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 12, 7, 'E quando viu o SENHOR que se haviam humilhado, foi palavra do SENHOR a Semaías, dizendo: Humilharam-se; não os destruirei; antes os salvarei em breve, e não se derramará minha ira contra Jerusalém por mão de Sisaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 12, 8, 'Porém serão seus servos; para que saibam que é servir a mim, e servir aos reinos das nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 12, 9, 'Subiu, pois, Sisaque, rei do Egito a Jerusalém, e tomou os tesouros da casa do SENHOR, e os tesouros da casa do rei; tudo o levou: e tomou os paveses de ouro que Salomão havia feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 12, 10, 'E em lugar deles fez o rei Roboão paveses de bronze, e entregou-os em mãos dos chefes da guarda, os quais guardavam a entrada da casa do rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 12, 11, 'E quando o rei ia à casa do SENHOR, vinham os da guarda, e traziam-nos, e depois os voltavam à câmara da guarda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 12, 12, 'E quando ele se humilhou, a ira do SENHOR se separou dele, para não destruí-lo de todo: e também em Judá as coisas foram bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 12, 13, 'Fortificou-se, pois Roboão, e reinou em Jerusalém: e era Roboão de quarenta e um anos quando começou a reinar, e dezessete anos reinou em Jerusalém, cidade que escolheu o SENHOR de todas as tribos de Israel, para pôr nela seu nome. E o nome de sua mãe foi Naamá, amonita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 12, 14, 'E fez o mal, porque não dispôs seu coração para buscar ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 12, 15, 'E as coisas de Roboão, primeiras e últimas, não estão escritas nos livros de Semaías profeta e de Ido vidente, no registro das linhagens? E entre Roboão e Jeroboão havia perpétua guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 12, 16, 'E descansou Roboão com seus pais, e foi sepultado na cidade de Davi: e reinou em seu lugar Abias seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 1, 'Aos dezoito anos do rei Jeroboão, reinou Abias sobre Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 2, 'E reinou três anos em Jerusalém. O nome de sua mãe foi Micaia filha de Uriel de Gibeá. E havia guerra entre Abias e Jeroboão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 3, 'Então ordenou Abias batalha com um exército de quatrocentos mil homens de guerra valentes e escolhidos: e Jeroboão ordenou batalha contra ele com oitocentos mil homens escolhidos, fortes e valentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 4, 'E levantou-se Abias sobre o monte de Zemaraim, que é nos montes de Efraim, e disse: Ouvi-me, Jeroboão e todo Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 5, 'Não sabeis vós, que o SENHOR Deus de Israel deu o reino a Davi sobre Israel para sempre, a ele e a seus filhos em aliança de sal?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 6, 'Porém Jeroboão filho de Nebate, servo de Salomão filho de Davi, se levantou e rebelou contra seu senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 7, 'E se achegaram a ele homens vãos, filhos de iniquidade, e puderam mais que Roboão filho de Salomão, porque Roboão era jovem e tenro de coração, e não se defendeu deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 8, 'E agora vós tratais de fortificar-vos contra o reino do SENHOR em mão dos filhos de Davi, porque sois muitos, e tendes convosco os bezerros de ouro que Jeroboão vos fez por deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 9, 'Não lançastes vós aos sacerdotes do SENHOR, aos filhos de Arão, e aos levitas, e vos haveis feito sacerdotes à maneira dos povos de outras terras, para que qualquer um venha a consagrar-se com um bezerro e sete carneiros, e assim seja sacerdote dos que não são Deuses?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 10, 'Mas em quanto a nós, o SENHOR é nosso Deus, e não lhe deixamos: e os sacerdotes que ministram ao SENHOR são os filhos de Arão, e os levitas na obra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 11, 'Os quais queimam ao SENHOR os holocaustos cada manhã e cada tarde, e os perfumes aromáticos; e põem os pães sobre a mesa limpa, e o candelabro de ouro com suas lâmpadas para que ardam cada tarde: porque nós guardamos a ordenança do SENHOR nosso Deus; mas vós o deixastes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 12, 'E eis que Deus está conosco por cabeça, e seus sacerdotes com as trombetas do júbilo para que soem contra vós. Ó filhos de Israel, não luteis contra o SENHOR o Deus de vossos pais, porque não vos sucederá bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 13, 'Porém Jeroboão preparou uma emboscada para vir a eles pela retaguarda: e estando assim diante deles, a emboscada estava à retaguarda de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 14, 'E quando olhou Judá, eis que tinha batalha diante e às costas; por isso que clamaram ao SENHOR, e os sacerdotes tocaram as trombetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 15, 'Então os de Judá levantaram grito; e assim que eles levantaram grito, Deus derrotou a Jeroboão e a todo Israel diante de Abias e de Judá:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 16, 'E fugiram os filhos de Israel diante de Judá, e Deus os entregou em suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 17, 'E Abias e sua gente faziam em eles grande mortandade; e caíram feridos de Israel quinhentos mil homens escolhidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 18, 'Assim foram humilhados os filhos de Israel naquele tempo: mas os filhos de Judá se fortificaram, porque se apoiavam no SENHOR o Deus de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 19, 'E seguiu Abias a Jeroboão, e tomou-lhe algumas cidades, a Betel com suas aldeias, a Jesana com suas aldeias, e a Efraim com suas aldeias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 20, 'E nunca mais teve Jeroboão poderio nos dias de Abias: e feriu-lhe o SENHOR, e morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 21, 'Porém se fortificou Abias; e tomou catorze mulheres, e gerou vinte e dois filhos, e dezesseis filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 13, 22, 'Os demais feitos de Abias, seus caminhos e seus negócios, estão escritos na história do profeta Ido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 14, 1, 'E Abias descansou com seus pais, e foi sepultado na cidade de Davi. E reinou em seu lugar seu filho Asa, em cujos dias aquela terra teve paz por dez anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 14, 2, 'E fez Asa o que era bom e correto aos olhos do SENHOR seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 14, 3, 'Porque tirou os altares do culto alheio, e os altos; quebrou as imagens, e arrancou os bosques;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 14, 4, 'E mandou a Judá que buscassem ao SENHOR o Deus de seus pais, e praticassem a lei e seus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 14, 5, 'Tirou também de todas as cidades de Judá os altos e as imagens, e esteve o reino quieto diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 14, 6, 'E edificou cidades fortes em Judá, porquanto havia paz na terra, e não havia guerra contra ele em aqueles tempos; porque o SENHOR lhe havia dado repouso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 14, 7, 'Disse por tanto a Judá: Edifiquemos estas cidades, e as cerquemos de muros com torres, portas, e barras, já que a terra é nossa: porque buscamos ao SENHOR nosso Deus, temos o buscado, e ele nos deu repouso de todas as partes. Edificaram, pois, e foram prósperos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 14, 8, 'Teve também Asa exército que trazia escudos e lanças: de Judá trezentos mil, e de Benjamim duzentos e oitenta mil que traziam escudos e flechavam arcos; todos eram homens hábeis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 14, 9, 'E saiu contra eles Zerá etíope com um exército de mil milhares, e trezentos carros; e vinho até Maressa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 14, 10, 'Então saiu Asa contra ele, e ordenaram a batalha no vale de Zefatá junto a Maressa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 14, 11, 'E clamou Asa ao SENHOR seu Deus, e disse: SENHOR, ninguém há mais que a ti para dar ajuda entre o grande e o que nenhuma força tem. Ajuda-nos, ó SENHOR Deus nosso, porque em ti nos apoiamos, e em teu nome viemos contra este exército. Ó SENHOR, tu és nosso Deus; não prevaleça contra ti o homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 14, 12, 'E o SENHOR derrotou os etíopes diante de Asa e diante de Judá; e fugiram os etíopes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 14, 13, 'E Asa, e o povo que com ele estava, o seguiu até Gerar: e caíram os etíopes até não haver neles resistência alguma; porque foram derrotados diante do SENHOR e de seu exército. E lhes tomaram muito grande despojo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 14, 14, 'Bateram também todas as cidades ao redor de Gerar, porque o terror do SENHOR foi sobre eles: e saquearam todas as cidades, porque havia nelas grande despojo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 14, 15, 'Assim atacaram as cabanas onde havia gado, e trouxeram muitas ovelhas e camelos, e voltaram a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 1, 'E foi o espírito de Deus sobre Azarias filho de Obede;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 2, 'E saiu ao encontro a Asa, e disse-lhe: Ouvi-me, Asa, e todo Judá e Benjamim: o SENHOR é convosco, se vós fordes com ele: e se lhe buscardes, será achado de vós; mas se lhe deixardes, ele também vos deixará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 3, 'Muitos dias esteve Israel sem verdadeiro Deus e sem sacerdote, e sem ensinador e sem lei:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 4, 'Mas quando em sua tribulação se converteram ao SENHOR Deus de Israel, e lhe buscaram, ele foi achado deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 5, 'Em aqueles tempos não havia paz, nem para o que entrava, nem para o que saía, mas sim muitas aflições sobre todos os habitantes das terras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 6, 'E a uma gente destruía à outra, e uma cidade a outra cidade: porque Deus os conturbou com todas as calamidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 7, 'Esforçai-vos, porém, vós, e não desfaleçam vossas mãos; que recompensa há para vossa obra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 8, 'E quando ouviu Asa as palavras e profecia de Obede profeta, foi confortado, e tirou as abominações de toda a terra de Judá e de Benjamim, e das cidades que ele havia tomado no monte de Efraim; e reparou o altar do SENHOR que estava diante do pórtico do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 14, '2 Crônicas', '2Cr', 15, 9, 'Depois fez juntar a todo Judá e Benjamim, e com eles os estrangeiros de Efraim, e de Manassés, e de Simeão: porque muitos de Israel se haviam passado a ele, vendo que o SENHOR seu Deus era com ele.')
